tmp_path = PosixPath('/pytest-of-user/pytest-221/test_owner_loss_stops_grader_a0') fault = 'SIGKILL'
@pytest.mark.parametrize('fault', ['SIGKILL', 'SIGTERM', 'exit']) def test_owner_loss_stops_grader_and_descendant_then_resumes(tmp_path, fault): root, job = make_blocked_job(tmp_path) store = Store.create(tmp_path / 'state.db', [job], root) # Match the imported implementation, even when pytest compares a pinned tree. import vare.runner source = Path(vare.runner.__file__).resolve().parents[1] script = '''import asyncio,os,signal,sys from vare.durable import Store,worker signal.signal(signal.SIGUSR1, lambda *_: os._exit(73)) asyncio.run(worker(Store(sys.argv[1]), 'lost-owner', 1)) ''' owner = subprocess.Popen([sys.executable, '-c', script, str(store.path)], cwd=tmp_path, env={**os.environ, 'PYTHONPATH': str(source)}, start_new_session=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL) receipt = {} evidence = {'fault': fault} try: assert until(lambda: (job.workspace / 'ready.json').exists()), 'grader never became ready' receipt = json.loads((job.workspace / 'ready.json').read_text()) assert running(receipt['grader']) and running(receipt['child']) assert store.jobs()[0]['state'] == 'running' injected = time.monotonic() owner.send_signal(signal.SIGUSR1 if fault == 'exit' else getattr(signal, fault)) owner.wait(timeout=5) stopped = until(lambda: not running(receipt['grader']) and not running(receipt['child']), 2) evidence.update(receipt=receipt, owner_exit=owner.returncode, stopped=stopped, stop_seconds=time.monotonic() - injected) > assert stopped, 'owner died but its grader or descendant kept running' E AssertionError: owner died but its grader or descendant kept running E assert False
